export class Queue {
    #items = [];
    get size() {
        return this.#items.length;
    }
    enqueue(value) {
        this.#items.push(value);
    }
    dequeue() {
        return this.#items.pop(); // 错误的实现：后进先出
    }
    peek() {
        return this.#items[this.#items.length - 1]; // 错误的实现：查看的是队尾
    }
}
